  const terms = query.toLowerCase().split(' ');
  let html = title;

  for (const term of terms) {
    const regex = new RegExp(`(${escapeRegex(term)})`, 'gi');
    html = html.replace(regex, '<mark>$1</mark>');
  }
  return html;
}

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
